    public Page<Xnx58> searchNotices(String keyword, Pageable pageable) {
        BooleanBuilder builder = new BooleanBuilder();


        if (StringUtils.hasText(keyword)) {
            builder.and(containsKeyword(keyword));
        }


        List<Xnx58> results = queryFactory.selectFrom(notice)
                .where(builder)
                .orderBy(notice.createdDate.desc())
                .offset(pageable.getOffset())
                .limit(pageable.getPageSize())
                .fetch();


        Long total = queryFactory.select(notice.count())
                .from(notice)
                .where(builder)
                .fetchOne();

        return new PageImpl<>(results, pageable, Objects.requireNonNullElse(total, 0L));
    }

    @Override
    public Page<Xnx58> searchNoticesByCategoryAndKeyword(Xwm58 category, String keyword, Pageable pageable) {
        BooleanBuilder builder = new BooleanBuilder();


        if (category != null) {
            builder.and(notice.category.eq(category));
        }


        if (StringUtils.hasText(keyword)) {
            builder.and(containsKeyword(keyword));
        }


        List<Xnx58> results = queryFactory.selectFrom(notice)
                .where(builder)
                .orderBy(notice.createdDate.desc())
                .offset(pageable.getOffset())
                .limit(pageable.getPageSize())
                .fetch();


        Long total = queryFactory.select(notice.count())
                .from(notice)
                .where(builder)
                .fetchOne();

        return new PageImpl<>(results, pageable, Objects.requireNonNullElse(total, 0L));
    }







    private BooleanExpression containsKeyword(String keyword) {
        return notice.title.containsIgnoreCase(keyword)
                .or(notice.content.containsIgnoreCase(keyword));
    }
